  trendToMonth = '';
  private readonly api = inject(AdminApiService); accounts: FinanceAccount[] = []; summary: FinanceSummary | null = null; transactions: FinanceTransaction[] = []; chartTransactions: FinanceTransaction[] = []; payrollLines: FinancePayrollLine[] = []; payrollTotals = { base: 0, bonus: 0, discount: 0, net: 0, paid: 0, due: 0 }; auditLogs: FinanceAuditLog[] = []; auditTransaction: FinanceTransaction | null = null; auditOpen = false; openActionId = ''; openTransaction = false; editingTransaction: FinanceTransaction | null = null; saving = false; error = ''; success = ''; search = ''; filterKind = ''; accountFilter = ''; payrollAccount = ''; transactionPage = 1; readonly transactionPageSize = 10; payrollPage = 1; readonly payrollPageSize = 10; applicationCategories = ['الأكواد','تسويق','المهندسين','مصروفات تشغيلية']; studioCategories = ['إيجار','أدوات ومستلزمات','مصاريف إدارية']; from = ''; to = ''; month = ''; draft: any = { kind:'expense', amount:null, occurredAt:'', accountId:'', category:'', counterparty:'', description:'' };
  ngOnInit() { const now = new Date(); this.month = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`; this.trendFromMonth = `${now.getFullYear()}-01`; this.trendToMonth = this.month; this.from = `${this.month}-01`; this.to = new Date(now.getFullYear(), now.getMonth()+1, 0).toISOString().slice(0,10); this.draft.occurredAt = this.to; if (this.payrollOnly && this.employeeOnly) this.loadPayroll(); else this.reload(); }
  get totalBalance() { return (this.summary?.balances || []).reduce((sum, item) => sum + Number(item.balance || 0), 0); }
  get transactionPages(): number { return Math.max(1, Math.ceil(this.transactions.length / this.transactionPageSize)); }
  get paginatedTransactions(): FinanceTransaction[] { const page = Math.min(Math.max(this.transactionPage, 1), this.transactionPages); const start = (page - 1) * this.transactionPageSize; return this.transactions.slice(start, start + this.transactionPageSize); }
