  get paginatedPayrollLines(): FinancePayrollLine[] { const page = Math.min(Math.max(this.payrollPage, 1), this.payrollPages); const start = (page - 1) * this.payrollPageSize; return this.payrollLines.slice(start, start + this.payrollPageSize); }
  get payrollPageNumbers(): Array<number | '…'> { return this.buildTransactionPaginationItems(Math.min(this.payrollPage, this.payrollPages), this.payrollPages); }
  get transactionCategories() { const list = this.transactionAccountId === 'studio' ? this.studioCategories : this.applicationCategories; const current = String(this.draft.category || ''); return current && !list.includes(current) ? [current, ...list] : list; }
  get transactionAccountId() { return this.editingTransaction?.accountId || this.draft.accountId || ''; }
   syncCategoryToAccount() { if (this.draft.category && !this.transactionCategories.includes(this.draft.category)) this.draft.category = ''; }
  get categoryEntries() { return Object.entries(this.summary?.byCategory || {}).sort((a,b) => b[1] - a[1]); }
  get chartPoints() { const points: Array<{ month: string; day: string; application: number; studio: number }> = []; if (!this.trendFromMonth || !this.trendToMonth) return points; const byMonth = new Map<string, { application: number; studio: number }>(); for (const item of this.chartTransactions.filter(row => row.status === 'posted')) { const key = item.occurredAt.slice(0, 7); const point = byMonth.get(key) || { application: 0, studio: 0 }; const sign = item.kind === 'income' ? 1 : item.kind === 'expense' ? -1 : 0; if (item.accountId === 'application') point.application += sign * item.amount; if (item.accountId === 'studio') point.studio += sign * item.amount; byMonth.set(key, point); } const cursor = new Date(`${this.trendFromMonth}-01T00:00:00`); const end = new Date(`${this.trendToMonth}-01T00:00:00`); while (cursor <= end) { const key = `${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,'0')}`; points.push({ month: key, day: key, ...(byMonth.get(key) || { application: 0, studio: 0 }) }); cursor.setMonth(cursor.getMonth() + 1); } return points; }
  get chartMax() { return Math.max(1, ...this.chartPoints.map(point => Math.max(Math.abs(point.application), Math.abs(point.studio)))); }
  barHeight(value: number) { return value === 0 ? 0 : Math.max(4, Math.round(Math.abs(value) / this.chartMax * 100)); }
  loadDemoData() { this.demoMode = true; this.error = ''; this.success = ''; this.from = `${this.month}-01`; this.to = `${this.month}-30`; this.accounts = [{ id:'application', name:'أبلكيشن', openingBalance:0, balance:95000, income:190000, expense:95000, net:95000, isActive:true }, { id:'studio', name:'استوديو', openingBalance:0, balance:45000, income:130000, expense:85000, net:45000, isActive:true }]; this.summary = { income:320000, expense:180000, transfer:0, net:140000, balances:this.accounts, byCategory:{ 'اشتراكات ومبيعات':320000, 'تسويق':45000, 'أدوات ومستلزمات':25000, 'رواتب':110000 } }; this.transactions = this.demoTransactions(); this.chartTransactions = this.transactions; this.payrollTotals = { base:110000, bonus:20000, discount:0, net:130000, paid:70000, due:60000 }; this.payrollLines = [{ employeeId:9001, employeeName:'موظف تجريبي — أبلكيشن', base:50000, bonus:10000, discount:0, net:60000, status:'paid' }, { employeeId:9002, employeeName:'موظف تجريبي — استوديو', base:40000, bonus:5000, discount:0, net:45000, status:'paid' }, { employeeId:9003, employeeName:'موظف تجريبي — دعم', base:20000, bonus:5000, discount:0, net:25000, status:'due' }]; if (!this.payrollAccount) this.payrollAccount = 'application'; }
  demoTransactions(): FinanceTransaction[] { const make = (id:string, kind:'income'|'expense', accountId:string, amount:number, day:string, category:string, counterparty:string, description:string): FinanceTransaction => ({ id, kind, accountId, amount, occurredAt:`${this.month}-${day}`, category, counterparty, description, status:'posted', createdBy:'demo', createdAt:new Date().toISOString() }); return [make('demo-income-1','income','application',120000,'02','اشتراكات ومبيعات','اشتراكات الطلاب','إيرادات اشتراكات أبلكيشن'), make('demo-income-2','income','application',70000,'08','اشتراكات ومبيعات','مبيعات','مبيعات أبلكيشن'), make('demo-income-3','income','studio',80000,'05','اشتراكات ومبيعات','اشتراكات الطلاب','إيرادات استوديو'), make('demo-income-4','income','studio',50000,'16','اشتراكات ومبيعات','مبيعات','مبيعات استوديو'), make('demo-expense-1','expense','application',55000,'10','رواتب','رواتب الفريق','رواتب أبلكيشن'), make('demo-expense-2','expense','application',40000,'19','تسويق','حملة إعلانية','تسويق أبلكيشن'), make('demo-expense-3','expense','studio',45000,'12','رواتب','رواتب الفريق','رواتب استوديو'), make('demo-expense-4','expense','studio',40000,'23','أدوات ومستلزمات','تشغيل','مستلزمات استوديو')]; }
  trendStartDate() { return this.trendFromMonth ? `${this.trendFromMonth}-01` : this.from; }
  trendEndDate() { if (!this.trendToMonth) return this.to; const [year, month] = this.trendToMonth.split('-').map(Number); return new Date(year, month, 0).toISOString().slice(0,10); }
  loadTrend() { if (!this.trendFromMonth || !this.trendToMonth) return; if (this.trendFromMonth > this.trendToMonth) { const value = this.trendFromMonth; this.trendFromMonth = this.trendToMonth; this.trendToMonth = value; } this.api.listFinanceTransactions({from:this.trendStartDate(),to:this.trendEndDate()}).subscribe({ next: value => this.chartTransactions=value.data, error: err => this.error=err?.error?.message || 'تعذر تحميل اتجاه الأرباح.' }); }
  buildTransactionPaginationItems(currentPage: number, totalPages: number): Array<number | '…'> { if (totalPages <= 5) return Array.from({ length: totalPages }, (_, index) => index + 1); const items: Array<number | '…'> = [1]; const start = Math.max(2, currentPage - 1); const end = Math.min(totalPages - 1, currentPage + 1); if (start > 2) items.push('…'); for (let page = start; page <= end; page += 1) items.push(page); if (end < totalPages - 1) items.push('…'); items.push(totalPages); return items; }
  goToTransactionPage(page: number | '…'): void { if (page === '…') return; this.transactionPage = Math.min(Math.max(page, 1), this.transactionPages); this.openActionId = ''; }
  goToPayrollPage(page: number | '…'): void { if (page === '…') return; this.payrollPage = Math.min(Math.max(page, 1), this.payrollPages); }
